// PromiseToSell Type (رسم وعد بالبيع)
interface PromiseToSell {
  // 1. بيانات الأطراف
  // أ. الملتزم بالبيع (البائع)
  seller?: {
    fullName?: string;
    dateOfBirth?: string;
    placeOfBirth?: string;
    nationality?: 'مغربي' | 'أجنبي' | '';
    idNumber?: string;
    address?: string;
    relationToProperty?: 'مالك' | 'وصي' | 'ممثل_قانوني' | '';
    isCapable?: boolean; // قادر قانونياً على التصرف
  };

  // ب. المتعهد له بالبيع (المشتري)
  buyer?: {
    fullName?: string;
    dateOfBirth?: string;
    placeOfBirth?: string;
    nationality?: 'مغربي' | 'أجنبي' | '';
    idNumber?: string;
    address?: string;
    relationToProperty?: 'قريب' | 'وصي' | 'محايد' | '';
    isCapable?: boolean;
  };

  // 2. بيانات العقار
  property?: {
    propertyType?: 'حضري' | 'فلاحي' | 'تجاري' | '';
    address?: string;
    registryOrDeed?: string; // سجل الأملاك / السند
    boundaries?: string;
    area?: string;
    totalValue?: number;
    encumbrances?: string; // الحقوق والرهونات القائمة
    status?: 'مؤجر' | 'محبس' | 'مرهون' | 'حر' | '';
    isShared?: boolean; // ملكية مشاعة
    hasWill?: boolean; // وصية على الممتلك
  };

  // 3. شروط وعد البيع
  promiseTerms?: {
    earnestMoney?: number; // العربون / الدفعة المسبقة
    totalPrice?: number; // السعر الكلي
    paymentMethod?: 'نقد' | 'تحويل_بنكي' | 'شيك' | '';
    finalDeadline?: string; // الأجل لإتمام العقد النهائي
    terminationCondition?: string; // شروط إنهاء العقد
    sellerGuarantees?: string; // ضمانات البائع
    agentAuthority?: string; // صلاحيات الوكيل
  };

  // 4. بيانات الوكيل (إن وجد)
  agent?: {
    name?: string;
    authorizationDate?: string;
    authorizationScope?: string; // نطاق التوكيل
    authorizingParty?: string; // جهة التوكيل
    isTimeLimited?: boolean;
    expiryDate?: string;
  };

  // 5. الشهود
  witnesses?: {
    witnessNames?: string;
    witnessResidences?: string;
    signaturesUploaded?: boolean;
  };

  // 6. التنبيهات والتحذيرات الذكية
  smartChecks?: {
    deadlineExceeded?: boolean; // تجاوز الأجل
    earnestNotPaid?: boolean; // العربون لم يُستوفَ
    propertyEncumbered?: boolean; // ممتلك محبوس/مرهون
    minorInvolved?: boolean; // قاصر متورط
    valuationMismatch?: boolean; // عدم توافق القيمة
    agentAuthorityExpired?: boolean; // صلاحية الوكيل انتهت
  };

  smartAnswers?: {
    sellerCapable?: boolean;
    buyerCapable?: boolean;
    requiresGuardian?: boolean;
    hasGuardian?: boolean;
    earnestRefundable?: boolean; // هل العربون قابل للاسترجاع
    buyerBreachLosesEarnest?: boolean; // هل المشتري يفقد العربون عند عدم الالتزام
  };
}

